// --------------------------------------------------------------------------------------------------------------------
// VR Battlegrounds patch 37: настройки ног из клипов (раздел «Ноги» UxrStandardAvatarController).
// --------------------------------------------------------------------------------------------------------------------
using System;
using UnityEngine;

namespace UltimateXR.Animation.IK
{
    /// <summary>SDK не зависит от игровой сборки: интеграция направляет диагностику ног в GameLog.Player.</summary>
    public static class UxrLegsDiagnostics
    {
        public static System.Action<string, UnityEngine.Object> WarningSink;
        public static void Warn(string message, UnityEngine.Object context) => WarningSink?.Invoke(message, context);
    }

    /// <summary>
    ///     VR Battlegrounds patch 37: настройки ног аватара — решатель ноги (<see cref="UxrLegIKSolver" />), клипы ходьбы на
    ///     копии рига и шаги (<see cref="UxrLegLocomotion" />). Хранятся в <c>UxrStandardAvatarController</c> рядом с IK
    ///     тела и рук; работает ими <see cref="UxrAnimatedLegs" />. Читаются каждый кадр — правка в Play видна сразу
    ///     (кроме копии рига и контроллера: они берутся при появлении копии).
    /// </summary>
    [Serializable]
    public sealed class UxrLegsSettings
    {
        #region Inspector Properties/Serialized Fields

        [Header("Решатель ноги")]
        [Tooltip("Куда смотрит колено: 0 — вперёд по тазу (колени всегда вперёд), 1 — за носком стопы (колено поворачивается вместе со стопой, например при шаге вбок). Обычно 0,5; меньше — колени меньше разворачиваются по ходу.")]
        [Range(0f, 1f)]
        public float kneeFollowsFoot = 0.5f;

        [Tooltip("Сколько ноги слушаются клипов: 1 — стопы ставит клип (обычно), 0 — ноги стоят в позе модели. Промежуточные значения — для отладки.")]
        [Range(0f, 1f)]
        public float legsWeight = 1f;

        [Header("Клипы ходьбы")]
        [Tooltip("Невидимая копия скелета этого аватара, на которой играют клипы ходьбы; с неё берутся позы стоп. Печётся утилитой «Tools/VR Battlegrounds/Avatars/Setup Legs», руками не менять.")]
        public GameObject locomotionRig;

        [Tooltip("Набор анимаций ходьбы (стойки без оружия / пистолет / винтовка, присед, повороты на месте). Пусто — контроллер самой копии рига. Собирается утилитой «Setup Legs».")]
        public RuntimeAnimatorController locomotionController;

        [Tooltip("Резкий отрыв тела от ног, м, после которого ноги не догоняют шагом, а сразу переставляются под тело (телепорт, респаун). Обычно 1–2; меньше — ноги «прыгают» при быстрых рывках.")]
        public float teleportDistance = 1.5f;

        [Tooltip("В наборе клипов есть поза на колене (клип приседа при Legs_Crouch = 1, как Rifle_IdleCrouching набора Mixamo). Включено — игрок опустил таз до таза этого клипа: аватар встаёт на колено клипа, колено держится на полу. Выключено (наборы без такого клипа, например клипы Final IK) — колена нет: присед только решателем — таз за головой, ноги сгибаются, колени вперёд, при очень низком тазе колено ставится на пол, стопы уходят под таз. Выставляет утилита «Setup Legs» по контроллеру.")]
        public bool hasKneelPose = true;

        [Tooltip("Когда садиться на колено (клип приседа набора), м без масштаба аватара: колено — полностью, когда таз игрока (оценка по шее из шлема и наклону корпуса) опустился до высоты таза в клипе колена; начинается — на столько выше. До этого полуприсед — стоячий клип с согнутыми ногами (и наклон корпуса — не колено). Обычно 0,12–0,15; больше — колено раньше игрока, меньше — переход резче.")]
        public float crouchBand = 0.13f;

        [Tooltip("Люфт оценки высоты таза для приседа, м: покачивание головы и дрожь шлема меньше этого не двигают присед у порога. Обычно 0,02–0,03.")]
        public float crouchHysteresis = 0.025f;

        [Tooltip("Ниже этой высоты над полом, м без масштаба, таз не опускается в приседе без позы на колене: голову ниже забирает наклон корпуса вперёд (голова остаётся в шлеме, таз уходит назад), а не провал таза под пол. На колене (поза клипа) минимум — таз клипа колена минус 0,1 м. Обычно 0,4.")]
        public float minPelvisHeight = 0.4f;

        [Tooltip("Колено клипа ниже этой высоты над полом, м без масштаба, считается стоящим на полу: оно остаётся на полу, даже если таз аватара ниже или выше таза клипа (колено и стопа переносятся вместе, колено не проходит сквозь пол и ноги не перекрещиваются). 0 — выключено. Обычно 0,15.")]
        public float kneeOnFloorHeight = 0.15f;

        [Tooltip("Высота сустава колена над полом, когда колено стоит на полу, м без масштаба. MEF: 0,06 (как в клипе колена набора винтовки).")]
        public float kneeFloorClearance = 0.06f;

        [Header("Таз")]
        [Tooltip("Насколько таз повторяет движение таза в клипе (покачивание, наклон при шаге). 1 — как в клипе, 0 — таз неподвижен и ноги идут «от бедра». Обычно 1.")]
        [Range(0f, 1f)]
        public float pelvisFromClip = 1f;

        [Tooltip("Насколько таз и ноги разворачиваются в сторону хода при шаге вбок. 1 — как в клипе (бёдра и колени заметно смотрят по ходу), 0 — таз смотрит прямо, ноги переступают боком. Клипы Mixamo — 0,75.")]
        [Range(0f, 1f)]
        public float pelvisYawFromClip = 0.75f;

        [Header("Наклон корпуса")]
        [Tooltip("Насколько корпус повторяет наклоны корпуса из клипа (наклон вперёд на бегу, покачивание). Голова при этом остаётся там, где шлем. 0 — спина прямая (только наклон на бегу ниже), 1 — как в клипе. Обычно 0,3–0,6.")]
        [Range(0f, 1f)]
        public float torsoFromClip = 0.5f;

        [Tooltip("Наклон корпуса аватара за наклоном игрока (шея ушла вперёд от места, где стоял таз) и чтобы таз не ушёл ниже минимума: голова остаётся в шлеме, таз уходит назад. Наклоняется весь корпус целиком (линия таз → шея). 1 — на угол оценки, 0 — корпус прямой (UltimateXR гнёт спину только от наклона головы > 60°). Обычно 0: наклон складывал корпус в низком приседе (до 77° таз → грудь), 2026-10-01.")]
        public float trunkLeanGain = 0f; // патч 39 (новое имя: прежнее neckLeanGain = 2 оставалось в памяти загруженных префабов)

        [Tooltip("Насколько корпус повторяет повороты плеч из клипа. Обычно 0: стойки с оружием развёрнуты к оружию, и корпус отворачивался бы от взгляда.")]
        [Range(0f, 1f)]
        public float torsoTwistFromClip;

        [Tooltip("Поправка силы наклона: до груди доходит только часть изгиба IK тела (веса Bend позвоночника), усиление это возмещает. Обычно 4 для MEF; если наклон выглядит слабым — больше.")]
        public float torsoBendGain = 4f;

        [Tooltip("Наклон корпуса вперёд на бегу, градусы при 3,5 м/с; шагом — без наклона. Работает, только если «Torso From Clip» = 0. Обычно 15–25; больше — бег «падающим» корпусом.")]
        [Range(0f, 60f)]
        public float runLean = 20f;

        [Header("Стопы и пол")]
        [Tooltip("Высота лодыжки над подошвой ботинка, м (без масштаба аватара); своя у каждой модели, считается утилитой «Setup Legs» по мешу обуви. Больше — подошва висит над полом, меньше — уходит в пол. MEF: 0,135.")]
        public float ankleHeight = 0.135f;

        [Tooltip("Ставить подошву на пол. Клипы сняты на другом скелете, и без этого стопа может висеть или уходить в пол на несколько сантиметров. Обычно включено.")]
        public bool groundFeet = true;

        [Tooltip("Скорость стопы, м/с, ниже которой стопа считается стоящей на полу (тогда по ней выравнивается высота подошвы). Обычно 0,2–0,3; больше — подошва «прилипает» к полу и в начале шага.")]
        public float plantedSpeed = 0.25f;

        [Tooltip("Плавность выравнивания подошвы по полу, с. Обычно 0,05; больше — стопа медленнее садится на пол после шага.")]
        public float groundSmoothTime = 0.05f;

        [Header("Шаги")]
        [Tooltip("Когда и как переставлять ноги вслед за игроком (перенос локомоции VRIK Animated).")]
        public UxrLegLocomotion locomotion = new UxrLegLocomotion();

        #endregion
    }
}
